<?php $rpg_tab='progress';include APPPATH.'views/learn/english_rpg/_tabs.php';$e=$data['episode']; ?><div class="container-xl"><div class="page-header"><div><div class="page-pretitle">Progres per Chapter</div><h2 class="page-title"><?= html_escape($e['title']); ?></h2><p class="text-secondary">Reset hanya tersedia jika chapter ini adalah chapter terakhir yang sedang atau baru dikerjakan pengguna.</p></div><div class="ms-auto"><a class="btn btn-outline-secondary" href="<?= base_url('learn-english-rpg/episode/'.$e['id']); ?>">Kembali ke Konten</a></div></div><?php foreach(['success','error'] as $f)if($this->session->flashdata($f)): ?><div class="alert alert-<?= $f==='success'?'success':'danger'; ?> mt-3"><?= html_escape($this->session->flashdata($f)); ?></div><?php endif; ?><div class="card mt-3"><div class="table-responsive"><table class="table table-vcenter"><thead><tr><th>Pengguna</th><th>Adegan</th><th>XP</th><th>Benar</th><th>Salah</th><th>Aktivitas</th><th>Status</th><th>Terakhir</th><th></th></tr></thead><tbody><?php foreach($data['players'] as $p): ?><tr><td><b><?= html_escape($p['full_name']?:$p['username']); ?></b><small class="d-block text-secondary"><?= html_escape($p['username']); ?></small></td><td><?= (int)$p['current_scene']; ?></td><td><?= (int)$p['xp']; ?></td><td><?= (int)$p['correct_answers']; ?></td><td><?= (int)$p['wrong_answers']; ?></td><td><?= (int)$p['activity_count']; ?></td><td><span class="badge bg-<?= $p['is_completed']?'success':'blue'; ?>-lt"><?= $p['is_completed']?'Selesai':'Berjalan'; ?></span></td><td><?= html_escape($p['updated_at']); ?></td><td><?php if($p['can_reset']): ?><?= form_open('learn-progress/rpg/episode/'.$e['id'].'/reset/'.$p['user_id'],['onsubmit'=>"return confirm('Reset chapter terakhir pengguna ini?')"]); ?><button class="btn btn-sm btn-outline-danger">Reset Chapter</button><?= form_close(); ?><?php else: ?><span class="text-secondary">Dikunci</span><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><